$messages = Message::orderBy('created_at', 'desc')
    ->offset(($page - 1) * 50)->limit(50)->get();
$total = Message::count();
foreach ($messages as $m) {
    $m->sender = Profile::where('user_id', $m->sender_id)->first()?->nickname;
    $m->room = TalkRoom::where('id', $m->talk_room_id)->first();
    $m->partner = TalkRoomMember::where('talk_room_id', $m->talk_room_id)
        ->where('user_id', '!=', $m->sender_id)->first();
}

