-- 10万件を並べ替えて 50件（created_at に索引がない）
select * from "messages"
order by "created_at" desc
limit 50 offset 0;

-- 全部の件数（10万行を数える）
select count(*) as "aggregate" from "messages";

-- 1件ごとに3本
select * from "profiles" where "user_id" = 23 limit 1;
select * from "talk_rooms" where "id" = 7 limit 1;
select * from "talk_room_members"
where "talk_room_id" = 7 and "user_id" != 23 limit 1;
